NLAlib.gramSoftMinLaplacian_eq_normalized.{u_1, u_2} {ι : Type u_1} {κ : Type u_2} [Fintype ι] [Fintype κ]
  [DecidableEq ι] [DecidableEq κ] [Nonempty ι] (n : ℕ) (hn : 0 < n) (ε : ℝ) (G : Matrix ι κ ℝ)
  (hpd : (NLAlib.regularizedGram ε G).PosDef) (b₀ : ℝ) (hb₀ : 0 < b₀) :
  have b := ⋯.eigenvalues;
  have ρ := fun i => b i / b₀;
  have l := fun i => (b i)⁻¹ - ε;
  have S := ∑ i, ρ i ^ n;
  have c := S ^ (-(↑n)⁻¹ - 1);
  NLAlib.gramSoftMinLaplacian n ε G =
    2 * ↑(Fintype.card κ) * c * ∑ i, ρ i ^ (n + 1) +
        4 * (↑n + 1) * b₀ * c * ((∑ i, l i * ρ i ^ (2 * n + 2)) / S - ∑ i, l i * ρ i ^ (n + 2)) -
      b₀ * c *
        ∑ i, ∑ j ∈ Finset.univ.erase i, (l i + l j) * ∑ a ∈ Finset.range (n + 1), ρ i ^ (n - a + 1) * ρ j ^ (a + 1)

