  have l := fun i => (b i)⁻¹ - ε;
  have T := ∑ i, b i ^ n;
  have c := T ^ (-(↑n)⁻¹ - 1);
  NLAlib.gramSoftMinLaplacian n ε G =
    2 * ↑(Fintype.card κ) * c * ∑ i, b i ^ (n + 1) +
        4 * (↑n + 1) * (T ^ (-(↑n)⁻¹ - 2) * ∑ i, l i * b i ^ (2 * n + 2) - c * ∑ i, l i * b i ^ (n + 2)) -
      c * ∑ i, ∑ j ∈ Finset.univ.erase i, (l i + l j) * ∑ a ∈ Finset.range (n + 1), b i ^ (n - a + 1) * b j ^ (a + 1)

