NLAlib.moorePenroseInverse_sub_blocks.{u_1, u_2} {m : Type u_1} {n : Type u_2} [Fintype m] [Fintype n] [DecidableEq m]
  [DecidableEq n] (A B : Matrix m n ℝ) :
  have a := NLAlib.moorePenroseInverse A;
  have b := NLAlib.moorePenroseInverse B;
  have P := A * a;
  have Q := b * B;
  Q * (b - a) * P = -b * (B - A) * a ∧
    Q * (b - a) * (1 - P) = b * (1 - P) ∧ (1 - Q) * (b - a) * P = -(1 - Q) * a ∧ (1 - Q) * (b - a) * (1 - P) = 0

